window.REPORT_PRELOAD_CACHE["WDC.html"] = {"version":"dc778bc9790566cc539820608bbc733573d2e9de2d5e0e6564886a25df21265d","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>西部数据 Western Digital (NASDAQ: WDC) 深度研究报告：从 NAND 闪存与 HDD 周期双擎复苏到分拆上市后 Flash 独立估值重估</title>\n  <!-- Tailwind CSS -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <!-- Chart.js -->\n  <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n  <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          fontFamily: {\n            sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n            mono: ['JetBrains Mono', 'monospace'],\n          },\n          colors: {\n            navy: {\n              950: '#060B14',\n              900: '#0F172A',\n              800: '#1E293B',\n              700: '#334155',\n            },\n            wdblue: {\n              400: '#38BDF8',\n              500: '#0066CC',\n              600: '#004C99',\n            },\n            accent: {\n              500: '#3B82F6',\n              600: '#2563EB',\n            },\n            teal: {\n              500: '#06B6D4',\n              600: '#0891B2',\n            }\n          }\n        }\n      }\n    }\n  </script>\n\n  <style>\n    /* 自定义滚动条与机构研报细节排版 */\n    ::-webkit-scrollbar {\n      width: 6px;\n      height: 6px;\n    }\n    ::-webkit-scrollbar-track {\n      background: transparent;\n    }\n    ::-webkit-scrollbar-thumb {\n      background: #94A3B8;\n      border-radius: 3px;\n    }\n    .dark ::-webkit-scrollbar-thumb {\n      background: #475569;\n    }\n\n    /* 打印友好优化 */\n    @media print {\n      #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n        display: none !important;\n      }\n      main {\n        margin-left: 0 !important;\n        padding: 0 !important;\n      }\n      section {\n        break-inside: avoid;\n      }\n    }\n\n    /* 卡片悬浮微光 */\n    .report-card {\n      transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n    }\n    .report-card:hover {\n      transform: translateY(-2px);\n    }\n\n    /* 侧边导航激活态 */\n    .nav-link.active {\n      background: linear-gradient(90deg, rgba(0, 102, 204, 0.26) 0%, rgba(56, 189, 248, 0.06) 100%);\n      border-left: 3px solid #38BDF8;\n      color: #FFFFFF;\n      font-weight: 600;\n    }\n  </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-wdblue-500 selection:text-white transition-colors duration-200\">\n\n  <!-- 顶部全局阅读进度条 -->\n  <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n    <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-wdblue-500 via-sky-400 to-amber-400 w-0 transition-all duration-150\"></div>\n  </div>\n\n  <!-- 移动端顶部导航栏 -->\n  <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n    <div class=\"flex items-center space-x-2.5\">\n      <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-wdblue-500 to-wdblue-600 flex items-center justify-center font-extrabold text-white shadow\">\n        WD\n      </div>\n      <div>\n        <div class=\"text-[11px] text-wdblue-400 font-semibold tracking-wider uppercase\">NASDAQ: WDC · Equity Research</div>\n        <div class=\"text-sm font-bold leading-tight\">西部数据深度研究报告</div>\n      </div>\n    </div>\n    <div class=\"flex items-center space-x-2\">\n      <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n        <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n        <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n      </button>\n      <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n        <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n      </button>\n    </div>\n  </header>\n\n  <!-- 移动端折叠抽屉菜单 -->\n  <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n    <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n    <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n      <div>\n        <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n          <span class=\"font-bold text-white text-base\">WDC 研报目录导航</span>\n          <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n          </button>\n        </div>\n        <ul class=\"mt-4 space-y-1.5 text-sm\">\n          <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n          <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与收入架构（Flash + HDD）</a></li>\n          <li><a href=\"#sec-spin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 闪存分拆上市与独立估值重估</a></li>\n          <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 行业周期地位与技术护城河</a></li>\n          <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康度与周期估值体系</a></li>\n          <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n          <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n        </ul>\n      </div>\n      <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n        <p>全球存储与半导体周期研究组</p>\n        <p class=\"mt-1\">数据基准：2026年11月 (FY26 / FY27E)</p>\n      </div>\n    </nav>\n  </div>\n\n  <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n  <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n    <div>\n      <!-- 机构品牌头 -->\n      <div class=\"p-5 border-b border-slate-800/80\">\n        <div class=\"flex items-center space-x-3\">\n          <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-wdblue-500 to-wdblue-600 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-wdblue-500/30\">\n            WDC\n          </div>\n          <div>\n            <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-wdblue-400 bg-wdblue-500/15 px-2 py-0.5 rounded\">NASDAQ: WDC</span>\n            <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">西部数据深度研究报告</h2>\n          </div>\n        </div>\n        <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n          NAND Flash 与大容量 HDD 双擎复苏 · 闪存独立分拆上市估值重估\n        </p>\n      </div>\n\n      <!-- 股票实时快照徽章 -->\n      <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">FY26E 营收共识</span>\n          <span class=\"font-mono font-bold text-white\">~$17.8B <span class=\"text-wdblue-400\">(+18.5%)</span></span>\n        </div>\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">毛利率 (Non-GAAP)</span>\n          <span class=\"font-mono font-bold text-amber-400\">~38.5% <span class=\"text-slate-400\">(周期上行)</span></span>\n        </div>\n        <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n          <span class=\"text-slate-400\">周期估值锚</span>\n          <span class=\"font-mono font-bold text-wdblue-400\">~12.5x P/E (分拆重估)</span>\n        </div>\n      </div>\n\n      <!-- 六个核心章节目录导航 -->\n      <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n        <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n        <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n          <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-wdblue-400 mr-2\">00</span>执行摘要与核心指标</span>\n          </a>\n          <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务架构（Flash + HDD）</span>\n          </a>\n          <a href=\"#sec-spin\" data-target=\"sec-spin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>闪存分拆上市与独立估值</span>\n          </a>\n          <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>行业地位与技术护城河</span>\n          </a>\n          <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与周期估值体系</span>\n          </a>\n          <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n          </a>\n          <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n          </a>\n        </nav>\n      </div>\n    </div>\n\n    <!-- 侧边栏底部工具栏 -->\n    <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n      <div class=\"flex items-center justify-between\">\n        <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n        <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition\">\n          <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n          <svg class=\"w-3.5 h-3.5 text-wdblue-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n          <span class=\"dark:hidden\">深色护眼模式</span>\n          <span class=\"hidden dark:inline\">机构亮色模式</span>\n        </button>\n      </div>\n      <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-wdblue-500 hover:bg-wdblue-600 text-white text-xs font-extrabold transition shadow-sm\">\n        <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n        <span>打印 / 导出 PDF 研报</span>\n      </button>\n    </div>\n  </aside>\n\n  <!-- 主内容区 -->\n  <main class=\"lg:ml-[280px] min-h-screen\">\n    <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n      <!-- =========================================================\n           00. Hero 研报封面区与执行摘要\n      ========================================================= -->\n      <section id=\"sec-exec\" class=\"scroll-mt-20\">\n        <!-- 顶部研报元数据标签栏 -->\n        <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n          <div class=\"flex flex-wrap items-center gap-2\">\n            <span class=\"px-2.5 py-1 rounded-md bg-wdblue-500/15 text-wdblue-600 dark:text-wdblue-400 font-bold border border-wdblue-500/30\">评级：买入 / 闪存分拆预期与周期复苏核心超配</span>\n            <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：FY2026–FY2027 Flash 与大容量 ePMR HDD 景气共振</span>\n          </div>\n          <div class=\"flex items-center space-x-3 font-mono\">\n            <span>覆盖时间：2026年11月</span>\n            <span>NASDAQ: WDC</span>\n          </div>\n        </div>\n\n        <!-- Hero 标题卡片 -->\n        <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-slate-900 to-[#0A1E3F] text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n          <!-- 背景西部数据蓝紫科技矩阵纹理 -->\n          <div class=\"absolute inset-0 opacity-15 pointer-events-none\" style=\"background-image: radial-gradient(#38BDF8 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n          <div class=\"relative z-10\">\n            <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-wdblue-500/20 border border-wdblue-400/40 text-wdblue-400 text-xs font-semibold mb-4\">\n              <span class=\"w-2 h-2 rounded-full bg-wdblue-400 animate-pulse\"></span>\n              <span>CORE THESIS · 存储双巨头分拆上市（Flash 独立） × 铠侠 BiCS Flash 联合体 × 阿里云/AI 数据湖超大容量 HDD 需求爆发</span>\n            </div>\n            <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n              西部数据 Western Digital (NASDAQ: WDC) 深度研究报告：从 NAND 闪存与 HDD 周期双擎复苏到分拆上市后 Flash 独立估值重估\n            </h1>\n            <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n              在经历行业历史上最严苛的去库存周期后，西部数据（WDC）凭借 <strong class=\"text-wdblue-400\">NAND 闪存价格回暖、BiCS 8/9 代技术升级与大容量 ePMR 垂直磁记录 HDD 在云数据中心的强劲出货</strong>，迎来基本面与估值的历史性双击。\n              随着 <strong class=\"text-white\">闪存业务分拆（Spin-off）独立上市</strong> 进程的稳步推进，资本市场对纯正 Flash 资产与传统磁盘业务将分别给予独立的倍数重估，FY2026E 总营收预计达 <strong class=\"text-wdblue-400\">~$17.8B (+18.5%)</strong>，盈利弹性显著释放。\n            </p>\n\n            <!-- 核心投资结论高亮条 -->\n            <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">Flash 闪存分拆预期驱动重估</div>\n                <div class=\"text-white font-semibold\">独立分拆为纯 Flash 龙头后，估值对标美光与闪存同行，打破母子架构折价</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">大容量云 HDD（ePMR/HAMR）景气</div>\n                <div class=\"text-wdblue-400 font-semibold\">AI 数据湖与超大规模云厂商对 24TB/28TB+ 氦气盘需求供不应求，毛利强势反弹</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">Non-GAAP 毛利率稳步回升至 38%+</div>\n                <div class=\"text-amber-400 font-semibold\">产能利用率满载叠加产品结构向高层数 BiCS 闪存及企业级 HDD 倾斜</div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- 4个核心 KPI 卡片 -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n          <!-- KPI 1 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>FY2026E 全年总营收</span>\n              <span class=\"p-1.5 rounded-lg bg-wdblue-500/15 text-wdblue-600 dark:text-wdblue-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$17.8B</span>\n              <span class=\"text-xs font-bold text-wdblue-600 dark:text-wdblue-400 bg-wdblue-500/15 px-2 py-0.5 rounded\">+18.5% YoY</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              闪存与硬盘双业务受益于 AI 存储架构升级，出货均价（ASP）与出货量实现量价齐升。\n            </p>\n          </div>\n\n          <!-- KPI 2 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>Non-GAAP 毛利率</span>\n              <span class=\"p-1.5 rounded-lg bg-amber-500/10 text-amber-600 dark:text-amber-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 3v2m6-2v2M9 19v2m6-2v2M5 9H3m2 6H3m18-6h-2m2 6h-2M7 19h10a2 2 0 002-2V7a2 2 0 00-2-2H7a2 2 0 00-2 2v10a2 2 0 002 2zM9 9h6v6H9V9z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">38.5%</span>\n              <span class=\"text-xs font-bold text-amber-600 dark:text-amber-400 bg-amber-500/10 px-2 py-0.5 rounded\">+8.2% YoY</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              相比行业底部时期的低谷毛利率实现戏剧性反转，成本优化与高端企业盘放量成效显著。\n            </p>\n          </div>\n\n          <!-- KPI 3 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>闪存 (Flash) 业务营收占比</span>\n              <span class=\"p-1.5 rounded-lg bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~54%</span>\n              <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2 py-0.5 rounded\">独立分拆标的</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              作为即将独立上市的纯 Flash 业务板块，其体量与美光、铠侠等同行并驾齐驱。\n            </p>\n          </div>\n\n          <!-- KPI 4 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>远期估值锚 (Fwd P/E)</span>\n              <span class=\"p-1.5 rounded-lg bg-indigo-500/10 text-indigo-600 dark:text-indigo-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~12.5x</span>\n              <span class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 bg-indigo-500/10 px-2 py-0.5 rounded\">估值重估潜力大</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              伴随周期顶点上行与分拆公告落地，PE 估值具有向 15x–18x 闪存行业平均水平靠拢的动能。\n            </p>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           一、 业务与收入架构 (Business & Revenue Architecture)\n      ========================================================= -->\n      <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-wdblue-600 dark:text-wdblue-400\">Section 01 · Business & Revenue Architecture</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与收入架构：Flash 闪存（54%）与 HDD 硬盘（46%）齐头并进</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">FY2026E 总营收 ~$17.8B · 双核互补驱动</span>\n        </div>\n\n        <!-- 交互式 Chart.js 双视图切换面板 -->\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n          <!-- 左侧：双视图图表 -->\n          <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n              <div>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">FY2022–FY2027E 闪存与 HDD 分部营收演进曲线</h3>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">Flash 与 HDD 随存储周期触底反弹，Flash 营收在 AI 存储需求下加速扩张</p>\n              </div>\n              <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n                <button onclick=\"switchBizChart('evolution')\" id=\"btn-chart-evo\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-wdblue-600 dark:text-wdblue-400 shadow-sm transition\">视图A：分部营收演进</button>\n                <button onclick=\"switchBizChart('split')\" id=\"btn-chart-split\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition\">视图B：终端应用占比</button>\n              </div>\n            </div>\n            <div class=\"relative h-72 w-full\">\n              <canvas id=\"bizArchitectureChart\"></canvas>\n            </div>\n          </div>\n\n          <!-- 右侧：结构性拆解核心洞察 -->\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">两大核心业务支柱与协同优势</h3>\n              <ul class=\"space-y-4 text-sm\">\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-wdblue-500/15 text-wdblue-600 dark:text-wdblue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">Flash 闪存业务（NAND & SSD）</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      与铠侠（Kioxia）通过合资公司（Flash Joint Venture）共享日本四日市与北上工厂产能。涵盖消费级、PC 级及企业级数据中心 NVMe SSD，正向 BiCS 8/9 代更高层数迈进。\n                    </p>\n                  </div>\n                </li>\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-amber-500/15 text-amber-600 dark:text-amber-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">HDD 硬盘业务（大容量云盘与客户端）</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      全球两大 HDD 巨头之一。凭借独家的 ePMR（能量辅助垂直磁记录）与氦气密封技术（Helium Seal），在超大规模数据中心（Hyperscale）大容量近线存储（Nearline HDD）市场占据领先份额。\n                    </p>\n                  </div>\n                </li>\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">AI 时代“热数据/冷数据”一体化覆盖</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      闪存满足 AI 模型训练与高速推理对低延迟的严苛要求，而超大容量 HDD 满足 PB 级训练数据集与冷数据备份的极致 TCO（总拥有成本）要求，形成完美互补。\n                    </p>\n                  </div>\n                </li>\n              </ul>\n            </div>\n            <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n              <span class=\"text-slate-500 dark:text-slate-400\">战略转型节点</span>\n              <span class=\"font-bold text-wdblue-600 dark:text-wdblue-400\">Flash 闪存独立分拆上市进行中</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- 四大核心业务与终端板块矩阵 -->\n        <div class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5\">\n          <!-- 板块 1：企业级 Flash SSD -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-wdblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-wdblue-500/15 text-wdblue-600 dark:text-wdblue-400 text-xs font-bold\">高增长引擎 · AI 基础设施</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">高速 SSD</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">1. 企业级与数据中心 SSD</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                面向云厂商与企业服务器的 PCIe Gen5/Gen4 NVMe 固态硬盘。受益于大模型微调、向量数据库缓存及 AI 训练集群的高速数据吞吐需求，出货量与 ASP 显著增长。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-wdblue-600 dark:text-wdblue-400 font-semibold\">\n              BiCS 8/9 世代良率攀升 · 成本优化显著\n            </div>\n          </div>\n\n          <!-- 板块 2：大容量近线 HDD -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-amber-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">高毛利现金牛 · 云计算底座</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">24TB/28TB+</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">2. 大容量近线 HDD (Nearline)</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                利用 ePMR 与 HelioSeal 氦气密封技术量产 24TB、28TB 及更高容量硬盘。全球云数据中心（AWS、微软 Azure、阿里云等）AI 数据湖扩容带动近线盘供不应求。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold\">\n              氦气密封专利壁垒 · 行业双寡头格局\n            </div>\n          </div>\n\n          <!-- 板块 3：客户端与消费级 Flash -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">周期回暖 · 消费换机</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">PC & 移动端</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">3. 客户端 SSD 与移动存储</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                涵盖笔记本电脑 OEM 固态硬盘、SanDisk 移动存储卡及 WD 品牌移动硬盘。伴随 AI PC 标配存储容量从 512GB 向 1TB/2บน 升级，终端单机容量价值量稳步提升。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold\">\n              SanDisk 零售品牌优势 · AI PC 升级红利\n            </div>\n          </div>\n\n          <!-- 板块 4：传统客户端与车载 HDD -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-indigo-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">稳健现金流 · 细分深耕</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">传统硬盘</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">4. 客户端与监控/车载 HDD</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                面向视频监控（Purple 紫盘）、NAS 存储（Red 红盘）及传统台式机与车载 DVR 的专业硬盘。虽然出货量受 SSD 替代呈结构性下滑，但凭借高毛利与长尾需求稳定贡献现金流。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold\">\n              垂直细分市场高壁垒 · 稳定现金回报\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           二、 闪存业务分拆上市与独立估值重估 (Spin-off Strategy)\n      ========================================================= -->\n      <section id=\"sec-spin\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · Flash Spin-off & Valuation Re-rating</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 闪存业务分拆上市与独立估值重估：剥离多元化折价，对标美光与铠侠</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">战略核心：Flash 纯正存储公司独立挂牌</span>\n        </div>\n\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n          <!-- 左侧：分拆逻辑与多维优势深度解析 -->\n          <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-wdblue-500/15 text-wdblue-600 dark:text-wdblue-400 flex items-center justify-center font-bold text-sm\">01</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">彻底打破“ conglomerate discount ”（多元化折价）</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                长期以来，WDC 同时拥有 NAND 闪存与机械硬盘（HDD）两项资产，资本市场在给予估值时往往由于两类业务周期错配产生折价。分拆后，纯 Flash 公司将直接对标美光（MU）等高成长存储芯片标的。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-amber-500/15 text-amber-600 dark:text-amber-400 flex items-center justify-center font-bold text-sm\">02</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">资本分配与研发投资的精准聚焦</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                独立后的 Flash 实体与 HDD 实体将各自拥有独立的资产负债表与融资渠道。Flash 能够更灵活地与铠侠（Kioxia）协调资本开支与产能投放，避免因 HDD 业务现金流波动受制肘。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">HDD 实体转型为“高现金流基础设施标的”</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                剥离重资产、高资本开支的闪存制造后，留下的 HDD 公司将具备极高的自由现金流转化率和类似公用事业/高股息基础设施的稳健财务特征，吸引偏好稳定回报的机构资金。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">行业并购与战略重组空间全面打开</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                分拆去除了潜在的反垄断与跨业务监管阻碍，未来 Flash 独立实体在全球 NAND 行业格局演进（如与铠侠进一步整合或战略联盟）中具备更高的运作灵活性。\n              </p>\n            </div>\n          </div>\n\n          <!-- 右侧：分拆前后估值结构对比卡片 -->\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm space-y-4\">\n            <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">分拆上市前后估值重估逻辑模拟</h3>\n            <div class=\"space-y-3 text-xs\">\n              <div class=\"p-3.5 rounded-xl bg-slate-50 dark:bg-navy-800/60 border border-slate-200 dark:border-slate-700\">\n                <div class=\"flex justify-between font-bold text-slate-900 dark:text-white mb-1\">\n                  <span>合并架构时期（当前现状）</span>\n                  <span class=\"text-slate-500\">PE ~10x–12x</span>\n                </div>\n                <p class=\"text-slate-600 dark:text-slate-300 leading-relaxed\">\n                  投资者按“周期性半导体混合体”定价，Flash 高增长弹性被 HDD 相对平稳的周期压制，整体估值存在 15%–25% 的综合折价。\n                </p>\n              </div>\n\n              <div class=\"p-3.5 rounded-xl bg-wdblue-500/10 border border-wdblue-500/30\">\n                <div class=\"flex justify-between font-bold text-wdblue-600 dark:text-wdblue-400 mb-1\">\n                  <span>分拆独立上市后（预期目标）</span>\n                  <span class=\"font-mono\">Flash PE 15x–18x + HDD PE 10x–12x</span>\n                </div>\n                <p class=\"text-slate-700 dark:text-slate-200 leading-relaxed\">\n                  纯 Flash 实体享受 AI 存储高成长多倍数溢价；HDD 实体享受高分红、高 FCF 现金牛估值。双实体加总市值（Sum-of-the-parts）显著高于分拆前。\n                </p>\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           三、 行业地位与技术护城河 (Industry Position & Moat)\n      ========================================================= -->\n      <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-wdblue-600 dark:text-wdblue-400\">Section 03 · Industry Position & Economic Moat</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 行业地位与技术护城河：BiCS 闪存联合体 + 氦气密封 HDD 双寡头壁垒</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：宽护城河 (Wide Moat · 存储制造与精密机械双极垄断)</span>\n        </div>\n\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n          <!-- 左侧：四大护城河解析 -->\n          <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-wdblue-500/15 text-wdblue-600 dark:text-wdblue-400 flex items-center justify-center font-bold text-sm\">01</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">与铠侠联合制造的规模化成本优势</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                通过与铠侠（Kioxia）长期稳定的合资工厂合作，WDC 在 NAND 闪存晶圆制造上享有全球前二的产能规模，通过联合研发有效分摊数百亿美元的资本开支与研发成本。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-amber-500/15 text-amber-600 dark:text-amber-400 flex items-center justify-center font-bold text-sm\">02</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">BiCS 8/9 代 3D NAND 高层数堆叠技术</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                推进更高层数的 3D NAND 闪存（BiCS 8 及下一代 BiCS 9），在单位面积内实现更高的存储密度与更低的每 GB 成本，确立了应对三星、SK海力士和美光竞争的技术底气。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">HeloSeal 氦气密封与 ePMR 机械硬盘寡头</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                全球仅剩 WDC 与希捷（Seagate）两家能够大规模量产大容量氦气近线盘。氦气密封减少内部空气摩擦，结合 ePMR 技术使 24TB/28TB+ 硬盘成为全球云数据中心不可替代的基础设施。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">全球一线云厂商与 OEM 深度认证粘性</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                企业级 SSD 与近线 HDD 需要经历长达 6–18 个月的严苛兼容性与可靠性测试。一旦进入云巨头（AWS、微软、谷歌、阿里云）供应商名录，客户粘性极高，不易被轻易替换。\n              </p>\n            </div>\n          </div>\n\n          <!-- 右侧：五维护城河雷达图 -->\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">存储双雄与闪存同行五维护城河雷达图</h3>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">Western Digital vs Micron (MU) vs Seagate (STX)（满分 10 分）</p>\n            <div class=\"relative h-72 w-full\">\n              <canvas id=\"moatRadarChart\"></canvas>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           四、 财务健康与周期估值体系 (Financial Health & Valuation)\n      ========================================================= -->\n      <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & Cyclical Valuation</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康度与周期估值体系：毛利率强劲修复与周期顶点盈利弹性</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">远期 P/E ~12.5x · 自由现金流转正并加速扩张</span>\n        </div>\n\n        <!-- 1. 财务健康度四大指标卡 -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-wdblue-600 dark:text-wdblue-400 uppercase\">Non-GAAP Gross Margin</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">38.5%</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              随着闪存合约价（ASP）触底回升及高毛利大容量近线 HDD 放量，毛利率从行业底部（&lt;20%）大幅飙升至近 39% 高位。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-amber-600 dark:text-amber-400 uppercase\">Non-GAAP Operating Income</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$2.8B</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              运营杠杆（Operating Leverage）充分释放，营收增长带来营业利润呈现几何级爆发。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Free Cash Flow</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$1.9B</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              现金流状况显著改善，支持资产负债表持续去杠杆并为未来的分拆上市奠定扎实财务基础。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase\">Net Debt / EBITDA</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">&lt; 1.5x</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              债务水平在周期上行期快速稀释下降，财务健康度回到历史安全稳健区间。\n            </p>\n          </div>\n        </div>\n\n        <!-- 2. 交互式 Chart.js 财务与估值双轴演进图 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">FY2022–FY2027E 营收与毛利率周期波动态势及估值演进</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400\">展示存储行业强周期特征：从 FY23 行业衰退谷底向 FY26/27 周期上行峰值的强劲修复曲线</p>\n            </div>\n            <span class=\"text-xs font-mono font-bold text-wdblue-600 dark:text-wdblue-400 bg-wdblue-500/10 px-2.5 py-1 rounded\">周期上行期盈利弹性极大</span>\n          </div>\n          <div class=\"relative h-72 w-full\">\n            <canvas id=\"valEvolutionChart\"></canvas>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           五、 投资决策与风险配置框架 (Investment Decision & Risk)\n      ========================================================= -->\n      <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-wdblue-600 dark:text-wdblue-400\">Section 05 · Investment Decision & Risk Allocation</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景推演与核心风险应对</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：把握分拆重估与 AI 存储周期共振窗口</span>\n        </div>\n\n        <!-- 1. 三情景估值推演卡片 (Bull / Base / Bear) -->\n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n          <!-- 牛市情景 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-wdblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-wdblue-500/15 text-wdblue-600 dark:text-wdblue-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n                <span class=\"font-mono text-xs font-bold text-wdblue-600 dark:text-wdblue-400\">概率：30%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标估值：16x – 18x P/E</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>闪存分拆上市进展顺利且资本市场给予极高的纯 Flash 估值溢价；同时 AI 数据中心对大容量 HDD 与企业级 SSD 需求持续超预期，营收冲向 $20B+。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-wdblue-600 dark:text-wdblue-400\">\n              潜在上行空间：+35% 至 +50%（分拆双击）\n            </div>\n          </div>\n\n          <!-- 基准情景 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-amber-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-amber-500/15 text-amber-600 dark:text-amber-400 text-xs font-bold\">基准情景 (Base Case)</span>\n                <span class=\"font-mono text-xs font-bold text-amber-600 dark:text-amber-400\">概率：50%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标估值：12x – 14x P/E</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>FY26E 营收如期实现 ~$17.8B 共识，毛利率保持 38% 左右，分拆方案稳步推进，估值在周期上行期向行业合理中枢回归。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-amber-600 dark:text-amber-400\">\n              潜在上行空间：+15% 至 +25%（基本面复利驱动）\n            </div>\n          </div>\n\n          <!-- 熊市情景 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-slate-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-slate-500/15 text-slate-600 dark:text-slate-300 text-xs font-bold\">熊市情景 (Bear Case)</span>\n                <span class=\"font-mono text-xs font-bold text-slate-600 dark:text-slate-300\">概率：20%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">防守估值：8x – 10x P/E</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>宏观经济放缓导致消费电子与 PC 存储需求再次陷入去库存周期，闪存价格出现阶段性回调，分拆上市进程由于资本市场波动延迟。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-slate-600 dark:text-slate-300\">\n              潜在下行回撤：-15% 至 -25%（存储周期底部支撑）\n            </div>\n          </div>\n        </div>\n\n        <!-- 2. 四大核心风险矩阵 -->\n        <div>\n          <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心风险评估与机构应对策略</h3>\n          <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 存储行业固有的强周期波动风险</span>\n                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">供需失衡导致的 ASP 价格剧烈波动</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                NAND 闪存作为标准大宗电子元器件，若同行（三星、SK海力士、美光）资本开支过度扩张恢复过快，可能导致供过于求并迅速侵蚀毛利率。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 分拆上市执行过程中的监管与税务摩擦</span>\n                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中高</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">分拆方案落地时间表不确定性</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                剥离重资产制造业务涉及复杂的资产债务切割、合资公司（铠侠）权益协调及税务安排，任何监管审批延误都可能对市场情绪造成短期扰动。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">03 · HDD 长期面临 SSD 替代的技术迭代风险</span>\n                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">客户端与低端机械硬盘份额被固态硬盘蚕食</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                随着 SSD 每 GB 成本持续下降，传统笔记本与台式机 HDD 几乎完全退出市场。虽大容量近线盘壁垒极高，但长期仍需警惕 NAND 成本下降带来的挤压效应。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">04 · 宏观经济波动与云厂商资本开支周期</span>\n                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">Hyperscalers AI 基础设施投入节奏变化</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                若全球主要云厂商未来因投资回报率（ROI）考量放缓数据中心服务器采购节奏，将直接影响 WDC 企业级 SSD 与近线 HDD 的出货量。\n              </p>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n      ========================================================= -->\n      <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n          </div>\n          <div class=\"flex items-center space-x-2 no-print\">\n            <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-wdblue-500/15 text-wdblue-600 dark:text-wdblue-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n            <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition\">重置清单</button>\n          </div>\n        </div>\n\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n            点击勾选机构季报追踪已验证达标的指标（状态自动本地保存），用高频产业里程碑动态验证分拆上市与周期复苏进展：\n          </p>\n\n          <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n            <!-- KPI 1 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"wdc-kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0066CC] focus:ring-wdblue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. NAND 闪存与 HDD 综合 ASP（平均销售单价）环比走势</span>\n                  <span class=\"text-[11px] font-mono text-wdblue-600 dark:text-wdblue-400 font-semibold shrink-0\">价格周期锚</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  跟踪每季度财报中的 Flash 每 GB 价格及 HDD 硬盘单价是否维持稳中有升，确认周期景气度持续性。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 2 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"wdc-kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0066CC] focus:ring-wdblue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 闪存分拆上市（Spin-off）法律及监管推进里程碑</span>\n                  <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">估值重估催化剂</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  监测管理层关于分拆实体的资产剥离公告、SEC 注册文件提交及挂牌时间表的最新官方指引。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 3 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"wdc-kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0066CC] focus:ring-wdblue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. Non-GAAP 毛利率是否稳定在 37%–40% 区间</span>\n                  <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">盈利质量锚</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  核查 BiCS 8/9 世代良率爬坡及 24TB/28TB 大容量 HDD 放量对整体毛利率的增厚效果。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 4 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"wdc-kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0066CC] focus:ring-wdblue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 大容量近线 HDD（Nearline）出货容量（EB 级）增速</span>\n                  <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">云存储需求锚</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  监测每季度售出的总艾字节（Exabytes）容量，验证云厂商 AI 数据湖扩容带来的近线硬盘需求强度。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 5 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"wdc-kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0066CC] focus:ring-wdblue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 自由现金流（FCF）净流入与资产负债表去杠杆进度</span>\n                  <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">财务安全指标</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  确认每季度是否有充沛的正向自由现金流用于偿还债务，确保分拆前两家实体均具备健康的财务结构。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 6 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"wdc-kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0066CC] focus:ring-wdblue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 企业级 SSD 在 AI 服务器中的订单渗透率</span>\n                  <span class=\"text-[11px] font-mono text-sky-600 dark:text-sky-400 font-semibold shrink-0\">AI 增量业务锚</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  追踪 PCIe Gen5 企业级固态硬盘在各大服务器厂商及云数据中心 AI 节点中的导入进展与市场份额。\n                </p>\n              </div>\n            </label>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           页脚免责声明 (Disclaimer Footer)\n      ========================================================= -->\n      <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n        <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n          <span>西部数据 Western Digital (NASDAQ: WDC) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n          <span>数据基准：FY2025 财报及 2026 年 11 月市场一致预期 (FY26 / FY27E)</span>\n        </div>\n        <p class=\"leading-relaxed\">\n          <strong>免责声明：</strong>本深度研究报告基于公司公开财务报告、全球存储行业供应链调研及市场一致预期数据整理生成，旨在提供结构化的产业分析与机构估值研究框架。报告中涉及的 FY2026E/FY2027E 营收预测、毛利率展望、闪存分拆上市预期及三情景估值模型均基于特定产业假设，不构成任何具体的证券买卖建议、要约或投资承诺。投资者在做出任何资产配置决策前，应结合自身风险承受能力与独立尽职调查审慎判断。\n        </p>\n      </footer>\n\n    </div>\n  </main>\n\n  <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n  <script>\n    // ==========================================\n    // 1. 亮色 / 深色模式切换（同步刷新所有 Chart.js 图表）\n    // ==========================================\n    function toggleTheme() {\n      const html = document.documentElement;\n      html.classList.toggle('dark');\n      updateChartsTheme();\n    }\n\n    // ==========================================\n    // 2. 移动端抽屉菜单切换\n    // ==========================================\n    function toggleMobileMenu() {\n      const drawer = document.getElementById('mobile-drawer');\n      drawer.classList.toggle('hidden');\n    }\n\n    // ==========================================\n    // 3. 阅读进度条与左侧导航滚动联动高亮\n    // ==========================================\n    const sections = document.querySelectorAll('section[id]');\n    const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n    window.addEventListener('scroll', () => {\n      const scrollTop = window.scrollY;\n      const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n      const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n      document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n      let currentId = 'sec-exec';\n      sections.forEach(sec => {\n        const top = sec.offsetTop - 160;\n        if (scrollTop >= top) {\n          currentId = sec.getAttribute('id');\n        }\n      });\n\n      navLinks.forEach(link => {\n        link.classList.remove('active');\n        const numSpan = link.querySelector('span span');\n        if (numSpan) {\n          numSpan.classList.remove('text-wdblue-400');\n          numSpan.classList.add('text-slate-500');\n        }\n        if (link.dataset.target === currentId) {\n          link.classList.add('active');\n          if (numSpan) {\n            numSpan.classList.remove('text-slate-500');\n            numSpan.classList.add('text-wdblue-400');\n          }\n        }\n      });\n    });\n\n    // ==========================================\n    // 4. KPI 核查清单状态持久化与计数更新\n    // ==========================================\n    const KPI_STORAGE_KEY = 'wdc_research_kpi_state_v1';\n\n    function loadKpiChecklist() {\n      try {\n        const saved = localStorage.getItem(KPI_STORAGE_KEY);\n        if (saved) {\n          const stateMap = JSON.parse(saved);\n          document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n            if (typeof stateMap[cb.id] === 'boolean') {\n              cb.checked = stateMap[cb.id];\n            }\n          });\n        }\n      } catch (e) {\n        // 忽略存储权限异常\n      }\n      updateKpiChecklist();\n    }\n\n    function updateKpiChecklist() {\n      const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n      const total = checkboxes.length;\n      let checkedCount = 0;\n      const stateMap = {};\n\n      checkboxes.forEach(cb => {\n        stateMap[cb.id] = cb.checked;\n        if (cb.checked) checkedCount++;\n      });\n\n      const pct = Math.round((checkedCount / total) * 100);\n      document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n      try {\n        localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n      } catch (e) {\n        // 忽略存储权限异常\n      }\n    }\n\n    function resetKpiChecklist() {\n      document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n        cb.checked = false;\n      });\n      updateKpiChecklist();\n    }\n\n    // ==========================================\n    // 5. Chart.js 数据可视化初始化与主题自适应\n    // ==========================================\n    let bizChartInstance = null;\n    let radarChartInstance = null;\n    let valEvolutionChartInstance = null;\n    let currentBizMode = 'evolution';\n\n    function getChartColors() {\n      const isDark = document.documentElement.classList.contains('dark');\n      return {\n        text: isDark ? '#CBD5E1' : '#475569',\n        grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n        radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n      };\n    }\n\n    function initBizChart() {\n      const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n      const colors = getChartColors();\n\n      // 视图 A：FY2022–FY2027E 分部营收演进（堆叠柱状图）\n      const evoConfig = {\n        type: 'bar',\n        data: {\n          labels: ['FY2022', 'FY2023', 'FY2024', 'FY2025', 'FY2026E', 'FY2027E'],\n          datasets: [\n            {\n              label: 'Flash 闪存业务 (NAND & SSD)',\n              data: [11.8, 8.2, 7.5, 9.4, 9.6, 11.5],\n              backgroundColor: '#0066CC',\n              borderRadius: 4,\n            },\n            {\n              label: 'HDD 硬盘业务 (近线盘 & 客户端盘)',\n              data: [8.6, 4.1, 4.5, 6.2, 8.2, 9.5],\n              backgroundColor: '#F59E0B',\n              borderRadius: 4,\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y}B`\n              }\n            }\n          },\n          scales: {\n            x: {\n              stacked: true,\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              stacked: true,\n              max: 25,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n            }\n          }\n        }\n      };\n\n      // 视图 B：终端应用占比（横向柱状图）\n      const splitConfig = {\n        type: 'bar',\n        data: {\n          labels: [\n            '云数据中心近线盘 (Nearline HDD)',\n            '企业级与服务器 SSD (Enterprise SSD)',\n            '客户端与 PC 固态硬盘 (Client SSD)',\n            '零售移动存储与数码 (SanDisk/WD)',\n            '车载、监控与传统消费硬盘 (HDD)'\n          ],\n          datasets: [\n            {\n              label: 'FY2026E 终端应用营收贡献 ($B)',\n              data: [7.2, 5.5, 3.2, 1.2, 0.7],\n              backgroundColor: [\n                '#F59E0B',\n                '#0066CC',\n                '#38BDF8',\n                '#06B6D4',\n                '#64748B'\n              ],\n              borderRadius: 6,\n              barThickness: 26\n            }\n          ]\n        },\n        options: {\n          indexAxis: 'y',\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: { display: false },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `营收规模: $${ctx.parsed.x}B (占总营收 ${(ctx.parsed.x / 17.8 * 100).toFixed(1)}%)`\n              }\n            }\n          },\n          scales: {\n            x: {\n              max: 10,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n            },\n            y: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      };\n\n      if (bizChartInstance) bizChartInstance.destroy();\n      bizChartInstance = new Chart(ctx, currentBizMode === 'evolution' ? evoConfig : splitConfig);\n    }\n\n    function switchBizChart(mode) {\n      currentBizMode = mode;\n      const btnEvo = document.getElementById('btn-chart-evo');\n      const btnSplit = document.getElementById('btn-chart-split');\n      const titleEl = document.getElementById('biz-chart-title');\n      const subEl = document.getElementById('biz-chart-sub');\n\n      if (mode === 'evolution') {\n        btnEvo.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-wdblue-600 dark:text-wdblue-400 shadow-sm transition';\n        btnSplit.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n        titleEl.textContent = 'FY2022–FY2027E 闪存与 HDD 分部营收演进曲线';\n        subEl.textContent = 'Flash 与 HDD 随存储周期触底反弹，Flash 营收在 AI 存储需求下加速扩张';\n      } else {\n        btnSplit.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-wdblue-600 dark:text-wdblue-400 shadow-sm transition';\n        btnEvo.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n        titleEl.textContent = 'FY2026E 主要终端应用营收贡献拆解（总计 ~$17.8B）';\n        subEl.textContent = '云数据中心近线盘与企业级 SSD 成为营收增长绝对顶梁柱';\n      }\n      initBizChart();\n    }\n\n    function initRadarChart() {\n      const ctx = document.getElementById('moatRadarChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (radarChartInstance) radarChartInstance.destroy();\n      radarChartInstance = new Chart(ctx, {\n        type: 'radar',\n        data: {\n          labels: [\n            'NAND 3D 堆叠与晶圆制造规模',\n            '大容量氦气近线盘技术专利 (ePMR)',\n            '云厂商与一线 OEM 客户认证粘性',\n            '闪存联合体成本分摊与供应链弹性',\n            '自由现金流转化与资产负债结构'\n          ],\n          datasets: [\n            {\n              label: 'Western Digital (WDC)',\n              data: [9.2, 9.6, 9.1, 9.4, 8.8],\n              borderColor: '#0066CC',\n              backgroundColor: 'rgba(0, 102, 204, 0.22)',\n              pointBackgroundColor: '#38BDF8',\n              borderWidth: 2.5\n            },\n            {\n              label: 'Micron (MU · 纯闪存与内存)',\n              data: [9.6, 5.0, 9.0, 8.5, 9.2],\n              borderColor: '#10B981',\n              backgroundColor: 'rgba(16, 185, 129, 0.12)',\n              pointBackgroundColor: '#10B981',\n              borderWidth: 1.8\n            },\n            {\n              label: 'Seagate (STX · 纯 HDD 龙头)',\n              data: [4.5, 9.7, 9.0, 6.0, 9.0],\n              borderColor: '#F59E0B',\n              backgroundColor: 'rgba(245, 158, 11, 0.12)',\n              pointBackgroundColor: '#F59E0B',\n              borderWidth: 1.5,\n              borderDash: [4, 4]\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n            }\n          },\n          scales: {\n            r: {\n              min: 0,\n              max: 10,\n              ticks: { display: false, stepSize: 2 },\n              grid: { color: colors.grid },\n              angleLines: { color: colors.radarAngle },\n              pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      });\n    }\n\n    function initValEvolutionChart() {\n      const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n      valEvolutionChartInstance = new Chart(ctx, {\n        type: 'bar',\n        data: {\n          labels: ['FY2022', 'FY2023', 'FY2024', 'FY2025', 'FY2026E', 'FY2027E'],\n          datasets: [\n            {\n              type: 'bar',\n              label: '全年总营收 ($B)',\n              data: [20.4, 12.3, 12.0, 15.6, 17.8, 20.2],\n              backgroundColor: 'rgba(0, 102, 204, 0.85)',\n              borderRadius: 5,\n              barThickness: 24,\n              yAxisID: 'y'\n            },\n            {\n              type: 'line',\n              label: 'Non-GAAP 毛利率 (%)',\n              data: [31.5, 14.2, 22.8, 33.5, 38.5, 41.0],\n              borderColor: '#F59E0B',\n              backgroundColor: '#F59E0B',\n              borderWidth: 3,\n              pointRadius: 5,\n              pointHoverRadius: 7,\n              tension: 0.25,\n              yAxisID: 'y1'\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => ctx.dataset.yAxisID === 'y'\n                  ? `${ctx.dataset.label}: $${ctx.parsed.y}B`\n                  : `${ctx.dataset.label}: ${ctx.parsed.y}%`\n              }\n            }\n          },\n          scales: {\n            x: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              type: 'linear',\n              position: 'left',\n              max: 25,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n            },\n            y1: {\n              type: 'linear',\n              position: 'right',\n              min: 0,\n              max: 50,\n              grid: { drawOnChartArea: false },\n              ticks: { color: '#F59E0B', font: { size: 11, weight: '600' }, callback: v => v + '%' }\n            }\n          }\n        }\n      });\n    }\n\n    function updateChartsTheme() {\n      initBizChart();\n      initRadarChart();\n      initValEvolutionChart();\n    }\n\n    window.addEventListener('DOMContentLoaded', () => {\n      loadKpiChecklist();\n      initBizChart();\n      initRadarChart();\n      initValEvolutionChart();\n    });\n  </script>\n</body>\n</html>\n"};
